**Untested paths:**
- Empty/null/undefined task → should default-route, not throw
- Task matching no pattern → fallback `coder` with confidence 0.5
- Each domain pattern (`api`, `ui`, `deploy`, …) routing to its agent
- Pattern ordering — first match wins; later overlapping patterns are shadowed
- Mixed-case tasks (regex is case-insensitive, but the lowercasing before the loop is redundant)

```js
// tests/router.test.js
const { routeTask, AGENT_CAPABILITIES } = require('../.claude/helpers/router.js');

describe('routeTask', () => {
  test('routes "implement a login page" to coder', () => {
    const r = routeTask('implement a login page');
    expect(r.agent).toBe('coder');
    expect(r.confidence).toBeGreaterThan(0.5);
  });

  test('routes test-related tasks to tester', () => {
    const r = routeTask('write unit tests for the auth module');
    expect(r.agent).toBe('tester');
  });

  test('routes API tasks to backend-dev', () => {
    const r = routeTask('create a REST api endpoint');
    expect(r.agent).toBe('backend-dev');
  });

  test('routes deploy tasks to devops', () => {
    const r = routeTask('deploy to docker and set up the pipeline');
    expect(r.agent).toBe('devops');
  });

  test('defaults to coder with lower confidence when no pattern matches', () => {
    const r = routeTask('something completely unrelated xyz123');
    expect(r.agent).toBe('coder');
    expect(r.confidence).toBe(0.5);
    expect(r.reason).toMatch(/default/i);
  });

  // EDGE CASE: empty string should not throw
  test('handles empty string without throwing', () => {
    expect(() => routeTask('')).not.toThrow();
    const r = routeTask('');
    expect(r.agent).toBeDefined();
  });

  // EDGE CASE: case-insensitive matching
  test('is case-insensitive', () => {
    const lower = routeTask('test the login flow');
    const upper = routeTask('TEST THE LOGIN FLOW');
    expect(lower.agent).toBe(upper.agent);
  });

  // MISSING: routeTask(null) and routeTask(undefined) — currently crashes
  // because `task.toLowerCase()` throws on null/undefined
  test.skip('handles null task gracefully', () => {
    expect(() => routeTask(null)).not.toThrow();
  });

  test('returns all required fields', () => {
    const r = routeTask('fix a bug');
    expect(r).toHaveProperty('agent');
    expect(r).toHaveProperty('confidence');
    expect(r).toHaveProperty('reason');
  });

  test('all returned agents exist in AGENT_CAPABILITIES', () => {
    const tasks = ['build feature', 'test it', 'review code', 'research docs',
                   'design system', 'create api', 'build ui', 'deploy app'];
    for (const task of tasks) {
      const { agent } = routeTask(task);
      expect(Object.keys(AGENT_CAPABILITIES)).toContain(agent);
    }
  });
});
