**Untested paths:**
- `get` with no key returns entire store
- `get` on non-existent key returns `undefined` (not an error)
- `set` with no key logs an error and does not write
- `set` always stamps `_updated`
- `delete` on non-existent key is a no-op (no throw)
- `keys` filters internal `_`-prefixed keys
- `loadMemory` on corrupt JSON falls back to `{}`
- All writes are atomic at the file level (no partial write observable)

```js
// tests/memory.test.js
const fs = require('fs');
const path = require('path');
const os = require('os');

// Point MEMORY_FILE at a temp dir so tests are isolated
let tmpDir;
beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'memory-test-'));
  process.chdir(tmpDir); // memory.js uses process.cwd()
});
afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

const commands = require('../.claude/helpers/memory.js');

describe('memory commands', () => {
  describe('set / get', () => {
    test('set then get returns value', () => {
      commands.set('foo', 'bar');
      const result = commands.get('foo');
      expect(result).toBe('bar');
    });

    test('set stamps _updated timestamp', () => {
      commands.set('x', '1');
      const all = commands.get();
      expect(all._updated).toBeDefined();
      expect(new Date(all._updated).getTime()).toBeGreaterThan(0);
    });

    test('get with no key returns whole store', () => {
      commands.set('a', '1');
      commands.set('b', '2');
      const all = commands.get();
      expect(all.a).toBe('1');
      expect(all.b).toBe('2');
    });

    test('get on non-existent key returns undefined', () => {
      const result = commands.get('nonexistent');
      expect(result).toBeUndefined();
    });

    // EDGE CASE: set with no key should not write to disk
    test('set with no key logs error and does not write', () => {
      const spy = jest.spyOn(console, 'error').mockImplementation(() => {});
      commands.set(undefined, 'value');
      spy.mockRestore();
      // Memory file should not have been created
      const memFile = path.join(tmpDir, '.claude-flow', 'data', 'memory.json');
      expect(fs.existsSync(memFile)).toBe(false);
    });
  });

  describe('delete', () => {
    test('deletes an existing key', () => {
      commands.set('key1', 'val1');
      commands.delete('key1');
      expect(commands.get('key1')).toBeUndefined();
    });

    // EDGE CASE: delete non-existent key should not throw
    test('deleting non-existent key does not throw', () => {
      expect(() => commands.delete('nope')).not.toThrow();
    });
  });

  describe('clear', () => {
    test('clears all keys', () => {
      commands.set('a', '1');
      commands.set('b', '2');
      commands.clear();
      expect(commands.get()).toEqual({});
    });
  });

  describe('keys', () => {
    test('returns only user keys, not internal _ keys', () => {
      commands.set('visible', 'yes');
      const keys = commands.keys();
      expect(keys).toContain('visible');
      expect(keys).not.toContain('_updated');
    });

    test('returns empty array on empty store', () => {
      expect(commands.keys()).toEqual([]);
    });
  });

  // INTEGRATION: corrupt JSON falls back to empty
  describe('error handling', () => {
    test('corrupt memory file is treated as empty store', () => {
      const dir = path.join(tmpDir, '.claude-flow', 'data');
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, 'memory.json'), 'NOT_JSON');
      expect(() => commands.get('x')).not.toThrow();
      expect(commands.get('x')).toBeUndefined();
    });
  });
});
```

