**Untested paths:**
- `start` generates a unique ID and writes `current.json`
- `restore` with no file prints "No session to restore" and returns null
- `restore` on existing session sets `restoredAt`
- `end` with no active session returns null
- `end` archives to `<id>.json` and removes `current.json`
- `metric` with a valid name increments; with unknown name does nothing and returns session
- `update` with no active session returns null
- `get` on missing session returns null
- `get` specific context key vs. whole context

```js
// tests/session.test.js
const fs = require('fs');
const path = require('path');
const os = require('os');

let tmpDir;
beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'session-test-'));
  process.chdir(tmpDir);
});
afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

const commands = require('../.claude/helpers/session.js');

describe('session commands', () => {
  describe('start', () => {
    test('creates current.json with a session id', () => {
      const session = commands.start();
      expect(session.id).toMatch(/^session-\d+$/);
      expect(session.startedAt).toBeDefined();
      expect(session.metrics.edits).toBe(0);

      const file = path.join(tmpDir, '.claude-flow', 'sessions', 'current.json');
      expect(fs.existsSync(file)).toBe(true);
    });

    test('two starts produce different IDs', () => {
      const s1 = commands.start();
      const s2 = commands.start();
      expect(s1.id).not.toBe(s2.id);
    });
  });

  describe('restore', () => {
    test('returns null when no session exists', () => {
      expect(commands.restore()).toBeNull();
    });

    test('restores existing session and sets restoredAt', () => {
      commands.start();
      const restored = commands.restore();
      expect(restored).not.toBeNull();
      expect(restored.restoredAt).toBeDefined();
    });
  });

  describe('end', () => {
    test('returns null when no session exists', () => {
      expect(commands.end()).toBeNull();
    });

    test('archives session and removes current.json', () => {
      const started = commands.start();
      commands.end();

      const sessionDir = path.join(tmpDir, '.claude-flow', 'sessions');
      const currentFile = path.join(sessionDir, 'current.json');
      const archiveFile = path.join(sessionDir, `${started.id}.json`);

      expect(fs.existsSync(currentFile)).toBe(false);
      expect(fs.existsSync(archiveFile)).toBe(true);

      const archived = JSON.parse(fs.readFileSync(archiveFile, 'utf-8'));
      expect(archived.endedAt).toBeDefined();
      expect(archived.duration).toBeGreaterThanOrEqual(0);
    });
  });

  describe('metric', () => {
    test('increments edits counter', () => {
      commands.start();
      commands.metric('edits');
      commands.metric('edits');
      const session = commands.status();
      expect(session.metrics.edits).toBe(2);
    });

    // EDGE CASE: unknown metric name — currently silently does nothing
    test('unknown metric name does not throw', () => {
      commands.start();
      expect(() => commands.metric('nonexistent')).not.toThrow();
    });

    test('returns null with no active session', () => {
      expect(commands.metric('edits')).toBeNull();
    });
  });

  describe('update / get', () => {
    test('stores and retrieves context values', () => {
      commands.start();
      commands.update('branch', 'main');
      expect(commands.get('branch')).toBe('main');
    });

    test('get with no key returns full context', () => {
      commands.start();
      commands.update('x', '1');
      commands.update('y', '2');
      const ctx = commands.get();
      expect(ctx).toEqual({ x: '1', y: '2' });
    });

    test('get with no session returns null', () => {
      expect(commands.get('anything')).toBeNull();
    });
  });
});
```

