The private functions (`tokenize`, `trigrams`, `jaccardSimilarity`, `deduplicateById`, `deduplicateByContent`, `fingerprintContent`, `computePageRank`, `buildEdges`) are not exported. **This is the primary structural test gap** — these are the most algorithmically complex parts of the codebase and have zero coverage.

**Recommendation:** Export them from `intelligence.cjs` under a `_testing` key gated on `NODE_ENV === 'test'`, or extract them into a separate `intelligence-utils.js` module.

```js
// tests/intelligence.test.js
// Requires extracting private helpers — see refactor note above.
// Skeleton assuming _testing export is added to intelligence.cjs:
//   if (process.env.NODE_ENV === 'test') module.exports._testing = { tokenize, trigrams, ... };

const os = require('os');
const fs = require('fs');
const path = require('path');
const intel = require('../.claude/helpers/intelligence.cjs');

let tmpDir;
beforeEach(() => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'intel-test-'));
  process.chdir(tmpDir);
});
afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

// ── Exported API ────────────────────────────────────────────────

describe('init', () => {
  test('returns nodes:0 when no store exists', () => {
    const result = intel.init();
    expect(result.nodes).toBe(0);
  });

  test('builds graph from a seeded store', () => {
    const storeDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(storeDir, { recursive: true });
    fs.writeFileSync(path.join(storeDir, 'auto-memory-store.json'), JSON.stringify([
      { id: 'a', key: 'auth', content: 'authentication module', namespace: 'core', createdAt: Date.now() },
      { id: 'b', key: 'db', content: 'database connection pool', namespace: 'core', createdAt: Date.now() },
    ]));

    const result = intel.init();
    expect(result.nodes).toBe(2);
    expect(result.edges).toBeGreaterThanOrEqual(0);
  });

  // EDGE CASE: store exceeds MAX_DATA_FILE_SIZE (10MB) → skipped, returns nodes:0
  test.skip('skips files larger than 10MB', () => {
    // Would require writing a 10MB+ file; omit in fast test suites, run in CI only
  });

  // EDGE CASE: graph cache hit (fresh within 60s) → returns cached result
  test('returns cache hit when graph is fresh', () => {
    const storeDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(storeDir, { recursive: true });
    const entry = { id: 'x', content: 'test', namespace: 'core', createdAt: Date.now() };
    fs.writeFileSync(path.join(storeDir, 'auto-memory-store.json'), JSON.stringify([entry]));

    intel.init(); // first call builds
    const second = intel.init(); // second call should hit cache
    expect(second.message).toMatch(/cache hit/i);
  });
});

describe('getContext', () => {
  test('returns null when no ranked context exists', () => {
    expect(intel.getContext('find something')).toBeNull();
  });

  test('returns null for empty prompt', () => {
    expect(intel.getContext('')).toBeNull();
    expect(intel.getContext(null)).toBeNull();
  });

  // EDGE CASE: prompt with only stop-words → tokenize returns [] → returns null
  test('returns null when prompt consists entirely of stop words', () => {
    const result = intel.getContext('the a an is are');
    expect(result).toBeNull();
  });

  test('returns context string when ranked entries exist and score threshold met', () => {
    const storeDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(storeDir, { recursive: true });
    fs.writeFileSync(path.join(storeDir, 'auto-memory-store.json'), JSON.stringify([
      { id: 'auth1', key: 'auth', content: 'authentication login password JWT token', namespace: 'core', createdAt: Date.now() },
    ]));
    intel.init();
    const ctx = intel.getContext('authentication JWT login');
    if (ctx !== null) {
      expect(ctx).toMatch(/INTELLIGENCE/);
    }
    // null is valid if score < 0.05; no assertion on exact value
  });
});

describe('recordEdit', () => {
  test('appends an entry to pending-insights.jsonl', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    intel.recordEdit('src/auth.js');

    const pending = path.join(dataDir, 'pending-insights.jsonl');
    expect(fs.existsSync(pending)).toBe(true);
    const line = JSON.parse(fs.readFileSync(pending, 'utf-8').trim().split('\n')[0]);
    expect(line.type).toBe('edit');
    expect(line.file).toBe('src/auth.js');
    expect(line.timestamp).toBeGreaterThan(0);
  });

  // EDGE CASE: missing file argument
  test('records "unknown" when file is not provided', () => {
    intel.recordEdit();
    const pending = path.join(tmpDir, '.claude-flow', 'data', 'pending-insights.jsonl');
    const line = JSON.parse(fs.readFileSync(pending, 'utf-8').trim());
    expect(line.file).toBe('unknown');
  });
});

describe('consolidate', () => {
  test('returns empty result when store does not exist', () => {
    const result = intel.consolidate();
    expect(result.entries).toBe(0);
  });

  test('promotes files edited 3+ times to insight entries', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });

    // Seed a store
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify([
      { id: 'a', content: 'some content', namespace: 'core', createdAt: Date.now() },
    ]));

    // Record 3 edits for the same file
    for (let i = 0; i < 3; i++) intel.recordEdit('hot/path.js');

    const result = intel.consolidate();
    expect(result.newEntries).toBe(1);
  });

  // EDGE CASE: deduplication — same file edited 3+ times across two consolidations
  // should only produce one insight entry (the `exists` guard)
  test('does not create duplicate insight for the same hot file', () => {
    const dataDir = path.join(tmpDir, '.claude-flow', 'data');
    fs.mkdirSync(dataDir, { recursive: true });
    fs.writeFileSync(path.join(dataDir, 'auto-memory-store.json'), JSON.stringify([]));

    for (let i = 0; i < 3; i++) intel.recordEdit('hot.js');
    intel.consolidate(); // creates insight

    for (let i = 0; i < 3; i++) intel.recordEdit('hot.js');
    const second = intel.consolidate(); // should not create a second one
    expect(second.newEntries).toBe(0);
  });
});

// ── Private helpers (require _testing export) ───────────────────

describe('computePageRank (via _testing)', () => {
  const { computePageRank } = intel._testing || {};
  const skip = !computePageRank;

  (skip ? test.skip : test)('single node has rank 1', () => {
    const ranks = computePageRank({ a: {} }, [], 0.85, 10);
    expect(ranks.a).toBeCloseTo(1, 5);
  });

  (skip ? test.skip : test)('empty graph returns {}', () => {
    expect(computePageRank({}, [], 0.85, 10)).toEqual({});
  });

  (skip ? test.skip : test)('converges for a simple two-node cycle', () => {
    const nodes = { a: {}, b: {} };
    const edges = [
      { sourceId: 'a', targetId: 'b' },
      { sourceId: 'b', targetId: 'a' },
    ];
    const ranks = computePageRank(nodes, edges, 0.85, 30);
    expect(ranks.a).toBeCloseTo(ranks.b, 3); // symmetric → equal rank
  });
});

describe('jaccardSimilarity (via _testing)', () => {
  const { jaccardSimilarity } = intel._testing || {};
  const skip = !jaccardSimilarity;

  (skip ? test.skip : test)('identical sets → 1', () => {
    const s = new Set(['a', 'b', 'c']);
    expect(jaccardSimilarity(s, s)).toBe(1);
  });

  (skip ? test.skip : test)('disjoint sets → 0', () => {
    expect(jaccardSimilarity(new Set(['a']), new Set(['b']))).toBe(0);
  });

  (skip ? test.skip : test)('both empty → 0 (not NaN)', () => {
    expect(jaccardSimilarity(new Set(), new Set())).toBe(0);
  });
});

describe('deduplicateByContent (via _testing)', () => {
  const { deduplicateByContent } = intel._testing || {};
  const skip = !deduplicateByContent;

  (skip ? test.skip : test)('keeps one entry when content is identical', () => {
    const entries = [
      { id: 'a', content: 'same text here' },
      { id: 'b', content: 'same text here' }, // duplicate by content
    ];
    const result = deduplicateByContent(entries);
    expect(result.length).toBe(1);
  });

  (skip ? test.skip : test)('prefers entry with higher accessCount', () => {
    const entries = [
      { id: 'a', content: 'hello world', accessCount: 1 },
      { id: 'b', content: 'hello world', accessCount: 10 },
    ];
    const result = deduplicateByContent(entries);
    expect(result[0].id).toBe('b');
  });

  (skip ? test.skip : test)('passes through null/non-array unchanged', () => {
    expect(deduplicateByContent(null)).toBeNull();
    expect(deduplicateByContent(undefined)).toBeUndefined();
  });
});
