**Untested paths:**
- `pre-bash` blocks known dangerous commands and exits with code 1
- `pre-bash` passes safe commands
- `post-edit` writes to `pending-insights.jsonl` (via intelligence)
- `route` calls `routeTask` and formats a banner
- Global 5 s safety timer forces exit 0 on hung hooks
- Unknown command → exit 0 with `[OK] Hook: <command>`
- No command → prints usage

```js
// tests/hook-handler.integration.test.js
const { execSync, spawnSync } = require('child_process');
const path = require('path');
const fs = require('fs');
const os = require('os');

const HANDLER = path.resolve(__dirname, '../.claude/helpers/hook-handler.cjs');

function run(command, stdinPayload, cwd) {
  return spawnSync(
    process.execPath,
    [HANDLER, command],
    {
      input: stdinPayload ? JSON.stringify(stdinPayload) : '',
      encoding: 'utf-8',
      cwd: cwd || os.tmpdir(),
      timeout: 6000,
    }
  );
}

describe('hook-handler.cjs integration', () => {
  let tmpDir;
  beforeEach(() => { tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'hh-test-')); });
  afterEach(() => fs.rmSync(tmpDir, { recursive: true, force: true }));

  describe('pre-bash', () => {
    test('blocks "rm -rf /" and exits 1', () => {
      const result = run('pre-bash', { command: 'rm -rf /' }, tmpDir);
      expect(result.status).toBe(1);
      expect(result.stderr).toMatch(/BLOCKED/);
    });

    test('passes a safe command and exits 0', () => {
      const result = run('pre-bash', { command: 'ls -la' }, tmpDir);
      expect(result.status).toBe(0);
      expect(result.stdout).toMatch(/OK/);
    });
  });

  describe('route', () => {
    test('outputs a routing banner and exits 0', () => {
      const result = run('route', { prompt: 'implement a new feature' }, tmpDir);
      expect(result.status).toBe(0);
      expect(result.stdout).toMatch(/Primary Recommendation/);
    });
  });

  describe('post-edit', () => {
    test('exits 0 and outputs [OK]', () => {
      const result = run('post-edit', { file_path: 'src/main.js' }, tmpDir);
      expect(result.status).toBe(0);
      expect(result.stdout).toMatch(/OK/);
    });
  });

  describe('unknown command', () => {
    test('exits 0 with pass-through message', () => {
      const result = run('totally-unknown-command', {}, tmpDir);
      expect(result.status).toBe(0);
      expect(result.stdout).toMatch(/OK/);
    });
  });

  describe('no command', () => {
    test('prints usage and exits 0', () => {
      const result = spawnSync(process.execPath, [HANDLER], {
        encoding: 'utf-8', cwd: tmpDir, timeout: 3000,
      });
      expect(result.status).toBe(0);
      expect(result.stdout).toMatch(/Usage/);
    });
  });
});
